def describe(index, sub=0):
    """把索引翻成可读描述；未核对时显式带「未核对」字样。

    工具显示一个索引时**必须**走这里：直接打印数字会让人以为它是
    已确认的厂家事实，而它可能只是 CiA 402 的惯例值。
    """
    if index == INDEX_UNSET:
        return "未核对"
    info = OD_BY_INDEX.get(index)
    if info is None:
        # 总线扫描会看到我们不认识的索引，那是正常现象，不该让工具崩。
        return "0x%04X:%d（不在本驱动的对象字典内）" % (index, sub)
    key, name, ent_sub, typ, usable, cite = info
    return "0x%04X:%d %s %s  [%s] %s" % (index, ent_sub, key, name, typ, cite)
